WITH g AS (SELECT season,h,holiday='Holiday' hol,count(*) n,avg(y) mean FROM hours WHERE functioning GROUP BY ALL), cells AS(SELECT a.n normal_n,b.n holiday_n,a.mean normal_mean,b.mean holiday_mean FROM g a JOIN g b USING(season,h) WHERE NOT a.hol AND b.hol AND a.n>=3 AND b.n>=3) SELECT count(*) cells,sum(holiday_n) holiday_n,sum(normal_mean*holiday_n)/sum(holiday_n) matched_normal,sum(holiday_mean*holiday_n)/sum(holiday_n) holiday FROM cells;
